"""Phase 2D: persisted, evidence-backed executor qualification for the client-side composition.

A qualification record says: THIS provider, run as THIS executable file (path + SHA-256 + reported version) with
THESE models, was qualified at THIS level on the strength of THIS evidence file. It is data in the client's own
state root (`<client_root>/control/supervisor/qualification/<provider>.json`), written only by a trusted
qualification run and re-validated on every load:

  * the executable must still resolve to the recorded file and hash to the recorded SHA-256;
  * `--version` must still report the recorded version;
  * the record digest must match (a hand-edited record is refused);
  * `FIXTURE_ONLY` records are honoured only when the composition explicitly allows fixtures (tests);
  * the recorded models become the bridge's `qualified_models` pin, so another model never inherits the evidence.

Anything that fails re-validation leaves the provider exactly where the frozen Phase 1 registry leaves it by
default: `NATIVE_UNQUALIFIED`, not usable, nothing executes. Authentication is never persisted: it is probed
live (`codex login status`, `claude auth status`) with the harness environment allow-list, never by reading a
credential file and never by logging in.
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import subprocess
import time
import uuid
from dataclasses import dataclass, replace
from pathlib import Path

from uri_core.client_runtime.harness import HarnessRegistry, harness_env, probe_version, resolve_command
from uri_supervisor.executors import BUILTIN_SPECS, GENERIC_NDJSON, ExecutorSpec

from .bridge import ExecutorBinding, _file_sha256, _same_file

SCHEMA = "uri.phase2d.qualification.v1"
LEVELS = ("NATIVE_QUALIFIED", "FIXTURE_ONLY")
_PROVIDER = re.compile(r"^[a-z][a-z0-9_]{0,63}$")
_MODEL = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:/-]{0,127}$")
_HEX64 = re.compile(r"^[0-9a-f]{64}$")
REQUIRED = ("schema", "provider", "level", "spec_id", "executable", "executable_args", "executable_sha256", "version",
            "models", "evidence_sha256", "evidence_path", "qualified_at", "qualified_by", "record_sha256")
# Live, read-only authentication status commands. Exit 0 = authenticated for Codex; Claude prints JSON.
AUTH_STATUS_ARGV = {"codex_cli": ("login", "status"), "claude_code": ("auth", "status")}
AUTH_VARS = {"claude_code": ("CLAUDE_CODE_OAUTH_TOKEN",), "codex_cli": ("CODEX_API_KEY", "CODEX_HOME")}


class QualificationError(ValueError):
    def __init__(self, code, detail=None):
        super().__init__(code if detail is None else f"{code}: {detail}")
        self.code, self.detail = code, detail


def qualification_dir(client_root) -> Path:
    return Path(client_root).resolve() / "control" / "supervisor" / "qualification"


def _canonical(record: dict) -> bytes:
    return json.dumps({k: v for k, v in record.items() if k != "record_sha256"}, sort_keys=True,
                      separators=(",", ":"), ensure_ascii=True).encode("utf-8")


def record_digest(record: dict) -> str:
    return hashlib.sha256(_canonical(record)).hexdigest()


def build_record(*, provider, level, spec_id, executable, executable_args, version, models, evidence_path,
                 qualified_by, notes=None) -> dict:
    """Build a record from observed facts. The caller is the trusted qualification run; this function only
    hashes what it is given (executable file, evidence file) and refuses malformed input."""
    if not isinstance(provider, str) or not _PROVIDER.fullmatch(provider):
        raise QualificationError("PROVIDER_ID_INVALID")
    if level not in LEVELS:
        raise QualificationError("LEVEL_INVALID", str(level))
    if spec_id not in BUILTIN_SPECS:
        raise QualificationError("SPEC_UNKNOWN", str(spec_id))
    exe = Path(executable)
    if not exe.is_file():
        raise QualificationError("EXECUTABLE_MISSING")
    args = [str(a) for a in (executable_args or [])]
    ev = Path(evidence_path)
    if not ev.is_file():
        raise QualificationError("EVIDENCE_MISSING")
    if not isinstance(models, (list, tuple)) or not models:
        raise QualificationError("MODELS_REQUIRED")
    for m in models:
        if m is not None and (not isinstance(m, str) or not _MODEL.fullmatch(m)):
            raise QualificationError("MODEL_ID_INVALID", str(m))
    if version is not None and not isinstance(version, str):
        raise QualificationError("VERSION_INVALID")
    record = {"schema": SCHEMA, "provider": provider, "level": level, "spec_id": spec_id,
              "executable": str(exe.resolve()), "executable_args": args, "executable_sha256": _file_sha256(exe),
              "version": version, "models": list(models), "evidence_sha256": _file_sha256(ev), "evidence_path": str(ev.resolve()),
              "qualified_at": time.strftime("%Y-%m-%dT%H:%M:%S"), "qualified_by": str(qualified_by), "notes": notes or ""}
    record["record_sha256"] = record_digest(record)
    return record


def write_record(client_root, record: dict) -> Path:
    """Atomic write of one provider's record (replaces an older record for the same provider)."""
    validate_shape(record)
    d = qualification_dir(client_root)
    d.mkdir(parents=True, exist_ok=True)
    path = d / (record["provider"] + ".json")
    tmp = path.with_name(path.name + "." + uuid.uuid4().hex + ".tmp")
    with open(tmp, "x", encoding="utf-8") as f:
        json.dump(record, f, indent=1, sort_keys=True)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)
    return path


def validate_shape(record) -> dict:
    if not isinstance(record, dict) or set(record) - set(REQUIRED) - {"notes"} or any(k not in record for k in REQUIRED):
        raise QualificationError("RECORD_SCHEMA")
    if record["schema"] != SCHEMA:
        raise QualificationError("RECORD_SCHEMA", "schema")
    if not isinstance(record["provider"], str) or not _PROVIDER.fullmatch(record["provider"]):
        raise QualificationError("RECORD_SCHEMA", "provider")
    if record["level"] not in LEVELS:
        raise QualificationError("RECORD_SCHEMA", "level")
    if record["spec_id"] not in BUILTIN_SPECS:
        raise QualificationError("RECORD_SCHEMA", "spec_id")
    if not isinstance(record["executable"], str) or not record["executable"]:
        raise QualificationError("RECORD_SCHEMA", "executable")
    if not isinstance(record["executable_args"], list) or any(not isinstance(a, str) for a in record["executable_args"]):
        raise QualificationError("RECORD_SCHEMA", "executable_args")
    for key in ("executable_sha256", "evidence_sha256", "record_sha256"):
        if not isinstance(record[key], str) or not _HEX64.fullmatch(record[key]):
            raise QualificationError("RECORD_SCHEMA", key)
    if record["version"] is not None and not isinstance(record["version"], str):
        raise QualificationError("RECORD_SCHEMA", "version")
    models = record["models"]
    if not isinstance(models, list) or not models or any(m is not None and (not isinstance(m, str) or not _MODEL.fullmatch(m)) for m in models):
        raise QualificationError("RECORD_SCHEMA", "models")
    if record_digest(record) != record["record_sha256"]:
        raise QualificationError("RECORD_DIGEST_MISMATCH")
    return record


def load_records(client_root) -> list:
    """Every record file, parsed or marked unreadable. Never raises for one bad file."""
    out = []
    d = qualification_dir(client_root)
    if not d.is_dir():
        return out
    for p in sorted(d.glob("*.json")):
        try:
            rec = json.loads(p.read_text(encoding="utf-8"))
            validate_shape(rec)
            if rec["provider"] != p.stem:
                raise QualificationError("RECORD_PROVIDER_FILENAME_MISMATCH")
            out.append({"path": str(p), "record": rec, "error": None})
        except (OSError, ValueError) as exc:
            code = exc.code if isinstance(exc, QualificationError) else "RECORD_UNREADABLE"
            out.append({"path": str(p), "record": None, "error": code})
    return out


def native_auth_probe(provider, executable, environ=None, timeout_s=30):
    """Live read-only authentication status. True / False / None (unknown). Never logs in, never reads a credential
    file: the CLI's own status command decides, under the same environment allow-list the executor gets."""
    argv = AUTH_STATUS_ARGV.get(provider)
    if argv is None:
        return None
    env = harness_env(AUTH_VARS.get(provider, ()), environ)
    try:
        p = subprocess.run([executable, *argv], capture_output=True, timeout=timeout_s, stdin=subprocess.DEVNULL, env=env)
    except (OSError, subprocess.TimeoutExpired):
        return None
    out = p.stdout.decode("utf-8", "replace")
    err = p.stderr.decode("utf-8", "replace")
    if provider == "claude_code":
        try:
            data = json.loads(out)
            return bool(data.get("loggedIn")) if isinstance(data, dict) else None
        except ValueError:
            return None
    # Codex 0.158.0 prints "Logged in using ChatGPT" on STDERR with exit 0 (Phase 2D defect D-D1: stdout alone read as
    # "not logged in"). "Not logged in" exits non-zero. Both streams are inspected; exit status decides first.
    text = (out + chr(10) + err).lower()
    if p.returncode != 0 or "not logged in" in text:
        return False
    return "logged in" in text


@dataclass(frozen=True)
class ClientComposition:
    registry: HarnessRegistry
    executors: dict
    report: list          # one row per record file: provider, status (QUALIFIED | INVALIDATED), reason, level, ...
    allow_fixture: bool

    def qualified(self):
        return sorted(r["provider"] for r in self.report if r["status"] == "QUALIFIED")


def _spec_for(record) -> ExecutorSpec:
    spec = BUILTIN_SPECS[record["spec_id"]]
    if record["level"] == "FIXTURE_ONLY":
        if record["spec_id"] != GENERIC_NDJSON.executor_id:
            raise QualificationError("FIXTURE_SPEC_REQUIRED")
        return replace(GENERIC_NDJSON, executor_id=record["provider"], stdin="instructions")
    if spec.executor_id != record["provider"]:
        raise QualificationError("SPEC_PROVIDER_MISMATCH")
    return spec


def revalidate(record, *, allow_fixture=False) -> tuple:
    """-> (spec, resolved executable, args) or raises QualificationError with the invalidation reason."""
    if record["level"] == "FIXTURE_ONLY" and not allow_fixture:
        raise QualificationError("LEVEL_NOT_ALLOWED", "FIXTURE_ONLY")
    spec = _spec_for(record)
    exe = record["executable"]
    cmd = resolve_command(exe)
    if not cmd or not Path(exe).is_file() or _same_file(cmd[0], exe) is not True:
        raise QualificationError("EXECUTABLE_MISSING")
    if _file_sha256(exe) != record["executable_sha256"]:
        raise QualificationError("EXECUTABLE_HASH_MISMATCH")
    for a in record["executable_args"]:
        if Path(a).is_absolute() and Path(a).suffix == ".py" and not Path(a).is_file():
            raise QualificationError("EXECUTABLE_ARGS_MISSING")
    probe = probe_version([exe, *record["executable_args"]])
    if not probe["installed"] or probe["version"] != record["version"] or record["version"] is None:
        raise QualificationError("VERSION_MISMATCH", f"{probe.get('version')} != {record['version']}")
    return spec, exe, list(record["executable_args"])


def compose_client(client_root, *, allow_fixture=False, auth_probe=None, environ=None, adapters_factory=None) -> ClientComposition:
    """Phase 1 `HarnessRegistry` (all adapters, nothing qualified) plus every persisted record that re-validates now.

    `auth_probe(harness_id) -> True|False|None` defaults to the live CLI status probe for providers with a valid record
    (fixture records are authenticated by definition) and None (AUTH_UNVERIFIED) for everything else."""
    from uri_harness_adapters import default_registry
    factory = adapters_factory or default_registry
    rows, executables, bindings, exe_of, levels = [], {}, {}, {}, {}
    for item in load_records(client_root):
        rec = item["record"]
        if rec is None:
            rows.append({"provider": Path(item["path"]).stem, "status": "INVALIDATED", "reason": item["error"], "path": item["path"]})
            continue
        try:
            spec, exe, args = revalidate(rec, allow_fixture=allow_fixture)
        except QualificationError as exc:
            rows.append({"provider": rec["provider"], "status": "INVALIDATED", "reason": exc.code, "detail": exc.detail,
                         "level": rec["level"], "path": item["path"]})
            continue
        executables[rec["provider"]] = [exe, *args]
        exe_of[rec["provider"]], levels[rec["provider"]] = exe, rec["level"]
        bindings[rec["provider"]] = ExecutorBinding(spec=spec, resolved_executable=exe, extra_argv=tuple(args), version=rec["version"],
                                                   executable_sha256=rec["executable_sha256"], qualified_models=tuple(rec["models"]))
        rows.append({"provider": rec["provider"], "status": "QUALIFIED", "reason": None, "level": rec["level"], "models": list(rec["models"]),
                     "executable": exe, "executable_sha256": rec["executable_sha256"], "version": rec["version"],
                     "evidence_sha256": rec["evidence_sha256"], "qualified_at": rec["qualified_at"], "path": item["path"]})

    def probe(harness_id):
        if harness_id not in exe_of:
            return None
        if levels[harness_id] == "FIXTURE_ONLY":
            return True
        if auth_probe is not None:
            return auth_probe(harness_id)
        return native_auth_probe(harness_id, exe_of[harness_id], environ)

    registry = factory(executables, auth_probe=probe)
    for row in rows:
        if row["status"] != "QUALIFIED":
            continue
        p = row["provider"]
        if p not in registry.adapters or registry.adapters[p].refused:
            row.update(status="INVALIDATED", reason="PROVIDER_REFUSED_OR_UNKNOWN")
            bindings.pop(p, None)
            continue
        registry.qualify(p, row["level"], row["evidence_sha256"])
    return ClientComposition(registry=registry, executors=bindings, report=rows, allow_fixture=bool(allow_fixture))
"""Phase 2D composition: the explicit, file-backed reasoning policy for the paired server and the client-side
composition that pairs it (persisted qualification -> Phase 1 registry + supervisor bindings -> bridge).

Server side. The frozen default composition lists exactly one row, the deterministic no-Brain source
(`uri_core.app.paired_server.default_composition`). Phase 2D does not change that file. Instead a Phase 2 server
profile reads an explicit policy file in the SERVER's own state root (`<state_root>/control/phase2_reasoning_policy.json`)
and lists its rows in addition to the deterministic one. A row is a (kind, provider, model) triple the owner chose to
offer; it is still only an *offer*: the client registry, the bridge and the ticket chain decide whether anything runs.
No row is ever inferred from an installed binary, a model advertisement or a client's claim.

Client side. `compose_client` (qualification.py) turns persisted, re-validated evidence into the Phase 1
`HarnessRegistry` qualification plus pinned `ExecutorBinding`s; `build_bridge` wires them into one `SupervisorBridge`.
"""
from __future__ import annotations

import json
import re
from pathlib import Path

from uri_core.core.paired_reasoning import ReasoningSelectionPolicy

from .bridge import SupervisorBridge
from .qualification import ClientComposition, compose_client

POLICY_SCHEMA = "uri.phase2d.reasoning_policy.v1"
DETERMINISTIC_ROW = ("server_local_model", "uri-deterministic", None)
# The only kind Phase 2 adds rows for. Cloud-model and server-local-model rows stay owner decisions outside Phase 2.
ALLOWED_KINDS = ("client_external_harness",)
QUALIFIED_CAPABILITIES = ("remember_fact", "external_harness_task")
_PROVIDER = re.compile(r"^[a-z][a-z0-9_]{0,63}$")
_MODEL = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:/-]{0,127}$")


class PolicyError(ValueError):
    pass


def policy_path(state_root) -> Path:
    return Path(state_root).resolve() / "control" / "phase2_reasoning_policy.json"


def load_policy_rows(path) -> frozenset:
    """Deterministic row + every valid row in the file. A malformed file is refused as a whole (fail closed: no
    harness rows), never partially accepted."""
    rows = {DETERMINISTIC_ROW}
    p = Path(path)
    if not p.is_file():
        return frozenset(rows)
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        raise PolicyError("POLICY_UNREADABLE") from None
    if not isinstance(data, dict) or data.get("schema") != POLICY_SCHEMA or not isinstance(data.get("rows"), list):
        raise PolicyError("POLICY_SCHEMA")
    for row in data["rows"]:
        if not isinstance(row, dict) or set(row) != {"kind", "provider", "model"}:
            raise PolicyError("POLICY_ROW_SHAPE")
        kind, provider, model = row["kind"], row["provider"], row["model"]
        if kind not in ALLOWED_KINDS:
            raise PolicyError("POLICY_KIND_NOT_ALLOWED")
        if not isinstance(provider, str) or not _PROVIDER.fullmatch(provider):
            raise PolicyError("POLICY_PROVIDER_INVALID")
        if model is not None and (not isinstance(model, str) or not _MODEL.fullmatch(model)):
            raise PolicyError("POLICY_MODEL_INVALID")
        rows.add((kind, provider, model))
    return frozenset(rows)


def write_policy(path, rows) -> Path:
    """Owner-side helper: write an explicit policy file. `rows` are (kind, provider, model) triples."""
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    rows = sorted({tuple(r) for r in rows} - {DETERMINISTIC_ROW}, key=str)   # the deterministic row is implied, never listed
    body = {"schema": POLICY_SCHEMA, "rows": [{"kind": k, "provider": pr, "model": m} for k, pr, m in rows]}
    load_policy_rows_from_data(body)
    p.write_text(json.dumps(body, indent=1, sort_keys=True), encoding="utf-8")
    return p


def load_policy_rows_from_data(data):
    import tempfile
    with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False, encoding="utf-8") as f:
        json.dump(data, f)
        name = f.name
    try:
        return load_policy_rows(name)
    finally:
        Path(name).unlink(missing_ok=True)


def phase2_server_composition(policy_file) -> dict:
    """`create_app(runtime, composition=...)` input for the Phase 2 server profile."""
    rows = load_policy_rows(policy_file)
    return {"policy": ReasoningSelectionPolicy(rows), "qualified": QUALIFIED_CAPABILITIES}


def build_bridge(client_root, composition: ClientComposition, **bridge_kwargs) -> SupervisorBridge:
    return SupervisorBridge(client_root, registry=composition.registry, executors=composition.executors, **bridge_kwargs)


def compose_and_build(client_root, *, allow_fixture=False, auth_probe=None, environ=None, **bridge_kwargs):
    comp = compose_client(client_root, allow_fixture=allow_fixture, auth_probe=auth_probe, environ=environ)
    return comp, build_bridge(client_root, comp, **bridge_kwargs)

"""Phase 2D worker-side service: the frozen worker protocol, served by the SupervisedTurnRunner.

Same commands and envelopes as the frozen `TurnService` (`turn_start`, `turn_intent`, `turn_decide`), so the
frozen UI client (`uri_ui/lib/services/paired_runtime.dart`) could drive it unchanged, plus two strict additions:

  * `turn_decide` MAY carry `approval_digest`: when present it must equal the digest of the approval request the
    worker showed for that turn; a mismatch drops the pending turn and refuses (`APPROVAL_DIGEST_MISMATCH`). A UI
    that echoes the digest it displayed therefore cannot approve a turn whose arguments changed underneath it. The
    worker still binds the approval to its own pending record either way (UI is never the authority).
  * `turn_cancel {turn_id}`: explicit withdrawal of a pending (not yet dispatched) turn. It is sent to the server as
    a denial, so nothing is ever executed for it. There is no mid-run cancel over this single-threaded protocol;
    the bridge's `cancel()` exists for an owning composition that runs the worker loop in a thread, and worker death
    propagates through the kill-on-close job (Phase 2A/2C evidence).

Pending state is memory-only, exactly as in the frozen service: a worker restart or reconnect drops every pending
turn (fail closed, `TURN_NOT_PENDING`), and the frozen server's own guards (`INTENT_EXECUTION_UNCERTAIN`,
`INTENT_ALREADY_EXECUTED`, duplicate operation ids) prevent a second execution of the same work.
"""
from __future__ import annotations

from uri_core.client_runtime.turn_runner import TurnError

from .runner import SupervisedTurnService

COMMAND_SCHEMAS = {
    "turn_start": ({"command", "session_id", "text", "reasoning"},),
    "turn_intent": ({"command", "session_id", "text", "reasoning", "intent_decision"},),
    "turn_decide": ({"command", "turn_id", "approve"}, {"command", "turn_id", "approve", "approval_digest"}),
    "turn_cancel": ({"command", "turn_id"},),
}


class SupervisedWorkerService(SupervisedTurnService):
    def handle(self, kind, command):
        shapes = COMMAND_SCHEMAS.get(kind)
        if shapes is None or set(command) not in shapes:
            raise TurnError("COMMAND_SCHEMA")
        if kind == "turn_cancel":
            entry = self.pending.pop(command["turn_id"], None)
            if entry is None:
                raise TurnError("TURN_NOT_PENDING")
            text, session, reasoning, turn = entry
            return self._public(self._runner().decide(text, session, reasoning, turn, False))
        if kind == "turn_decide":
            turn_id = command["turn_id"]
            if not isinstance(turn_id, str) or not isinstance(command["approve"], bool):
                self.pending.pop(turn_id, None) if isinstance(turn_id, str) else None
                raise TurnError("TURN_NOT_PENDING")
            if "approval_digest" in command:
                entry = self.pending.get(turn_id)
                shown = ((entry[3].get("approval_request") or {}).get("approval_digest")) if entry else None
                if entry is None or not isinstance(command["approval_digest"], str) or command["approval_digest"] != shown:
                    self.pending.pop(turn_id, None)
                    raise TurnError("APPROVAL_DIGEST_MISMATCH" if entry is not None else "TURN_NOT_PENDING")
                command = {k: v for k, v in command.items() if k != "approval_digest"}
        return super().handle(kind, command)
                    kind = command.get("command")
                    required = {"identity": {"command", "nonce"}, "snapshot": {"command", "session_id", "queries"},
                                "consent": {"command", "mutations"}, "commit": {"command", "mutations"},
                                "close": {"command"}, "session": {"command"}, "preflight": {"command"},
                                "server_request": {"command", "method", "path", "body"},
                                "harness_discover": {"command"},
                                "turn_start": {"command", "session_id", "text", "reasoning"},
                                "turn_intent": {"command", "session_id", "text", "reasoning", "intent_decision"},
                                "turn_decide": {"command", "turn_id", "approve"},
                                "turn_cancel": {"command", "turn_id"}}
                    if kind not in required or not (set(command) == required[kind]
                                                    or (kind == "turn_decide" and set(command) == required[kind] | {"approval_digest"})):
                        raise ValueError("COMMAND_SCHEMA")
                    if kind == "identity":
                        nonce = command["nonce"]
                        if not isinstance(nonce, str) or len(nonce) != 64 or any(c not in "0123456789abcdef" for c in nonce):
                            raise ValueError("NONCE_INVALID")
                        identity = {"client_id": m["client_id"], "server_id": m["server_id"],
                            "manifest_digest": manifest.digest, "generation": generation, "pid": process.pid,
                            "create_time": process.create_time(), "nonce": nonce}
                        result = {**identity, "signature": key.sign(canonical(identity)).hex()}
                    elif kind == "preflight":
                        from uri_core.client_runtime.readiness import client_preflight
                        result = {**client_preflight(manifest), "worker_profile": "phase2d-supervised",
                                  "production_cutover": False}
                    elif kind == "snapshot":
                        result = persistence.snapshot(command["session_id"], [ReadQuery.model_validate(q) for q in command["queries"]]).model_dump()
                    elif kind in {"consent", "commit"}:
                        mutation_set = ClientMutationSet.model_validate(command["mutations"])
                        if kind == "consent":
                            persistence.consent(mutation_set)
                            result = {"state": "CONSENT_RECORDED"}
                        else:
                            result = persistence.commit(mutation_set)
                    elif kind == "harness_discover":
                        result = {"harnesses": harnesses.discover(), "fallback": "none",
                                  "qualification": composition.report, "supervisor": "uri_supervisor_bridge"}
                    elif kind in {"turn_start", "turn_intent", "turn_decide", "turn_cancel"}:
                        result = turns.handle(kind, command)
                    elif kind in {"session", "server_request"}:
                        from uri_core.client_runtime.transport import ClientTransport
                        transport = ClientTransport(manifest)
                        if kind == "session":
                            result = transport.session()
                        else:
                            if command["method"] not in {"GET", "POST"}:
                                raise ValueError("METHOD_INVALID")
                            result = transport.request(command["method"], command["path"], command["body"])
                    else:
                        write_frame(sys.stdout.buffer, {"result": "CLOSED"})
                        break
                    write_frame(sys.stdout.buffer, {"result": "OK", "value": result})
                except (PersistenceError, TransportError, StatePortError, RuntimeIdentityError, TurnError) as error:
                    write_frame(sys.stdout.buffer, {"result": "REFUSED", "code": str(getattr(error, "code", error))})
                except Exception:
                    write_frame(sys.stdout.buffer, {"result": "REFUSED", "code": "CLIENT_COMMAND_REFUSED"})
            bridge.close()
        return 0
    except Exception:
        print("CLIENT_WORKER_REFUSED", file=sys.stderr)
        return 1


